INSERT INTO `v1_deba2d090321f3228f801bbe8305ab8f9829d138251d5d216c49ad2c7d389cd4` VALUES ("", "", 10, "", 1, "", "うわぁ～…！\n大きくなりすぎて\nやばいですね☆", 105831, "", 1010020, 11);
INSERT INTO `v1_deba2d090321f3228f801bbe8305ab8f9829d138251d5d216c49ad2c7d389cd4` VALUES ("", "", "", "", 1, "", "", 0, "", 1010021, 91);
INSERT INTO `v1_deba2d090321f3228f801bbe8305ab8f9829d138251d5d216c49ad2c7d389cd4` VALUES ("", "", 10, "", 1, "", "うえきちゃんが\nどこまで続くのか\n分からないほどです", 105931, "", 1010022, 11);
INSERT INTO `v1_deba2d090321f3228f801bbe8305ab8f9829d138251d5d216c49ad2c7d389cd4` VALUES ("", "", "", "", 1, "", "", 0, "", 1010023, 91);
INSERT INTO `v1_deba2d090321f3228f801bbe8305ab8f9829d138251d5d216c49ad2c7d389cd4` VALUES ("", "", 10, "", 1, "", "こういうのってさ\n上がどうなってるか\n見てみたいよね！", 112631, "", 1010024, 11);
INSERT INTO `v1_deba2d090321f3228f801bbe8305ab8f9829d138251d5d216c49ad2c7d389cd4` VALUES ("", "", "", "", 1, "", "", 0, "", 1010025, 91);
INSERT INTO `v1_deba2d090321f3228f801bbe8305ab8f9829d138251d5d216c49ad2c7d389cd4` VALUES ("", "", 10, "", 1, "", "確かにね…それに\nこうなった理由も\n分かるかも", 112531, "", 1010026, 11);
INSERT INTO `v1_deba2d090321f3228f801bbe8305ab8f9829d138251d5d216c49ad2c7d389cd4` VALUES ("", "", "", "", 1, "", "", 0, "", 1010027, 91);
INSERT INTO `v1_deba2d090321f3228f801bbe8305ab8f9829d138251d5d216c49ad2c7d389cd4` VALUES ("", "", 10, "", 1, "", "ま、興味はあるし\n付き合ってあげるわ", 106031, "", 1010028, 11);
INSERT INTO `v1_deba2d090321f3228f801bbe8305ab8f9829d138251d5d216c49ad2c7d389cd4` VALUES ("", "", "", "", 1, "", "", 0, "", 1010029, 91);
INSERT INTO `v1_deba2d090321f3228f801bbe8305ab8f9829d138251d5d216c49ad2c7d389cd4` VALUES ("", "", 10, "", 1, "", "はい♪みなさんで\n頂上を目指して\n頑張りましょう！", 112431, "", 1010030, 11);
INSERT INTO `v1_deba2d090321f3228f801bbe8305ab8f9829d138251d5d216c49ad2c7d389cd4` VALUES ("", "", "", "", 1, "", "", 0, "", 1010031, 91);
